const IDX_GLASS = 14;
const IDX_BOUNCE = 15;
const IDX_LIGHT = 16;
const IDX_WATER = 17;
const IDX_LEAVES = 18;
const IDX_GOLD = 19;
const IDX_FLOWER = 20;
const IDX_DOOR = 21;
const IDX_CONFETTI = 22;
